//! The strongly-typed id types for every entity (one per table in `schema.md` §7).
//!
//! Each is a transparent newtype over `String` generated by [`id_core::define_id!`], so it
//! carries its prefix, `generate()`s time-ordered ULIDs, validates on `FromStr`, and plugs into
//! sqlx `query_as!` column overrides. Passing a `UserId` where an `AccountId` is expected is a
//! compile error — that is the entire point. NEVER use bare `String` ids.

use id_core::define_id;

pub use id_core::ParseIdError;

