#[cfg(test)]
mod tests {
  use super::*;
  use std::str::FromStr;

  #[test]
  fn generate_has_prefix() {
    assert!(UserId::generate().as_str().starts_with("user_"));
    assert!(AccountId::generate().as_str().starts_with("acct_"));
    assert_eq!(UserId::PREFIX, "user");
  }

  #[test]
  fn from_str_roundtrip() {
    let id = UserId::generate();
    let parsed = UserId::from_str(id.as_str()).unwrap();
    assert_eq!(parsed, id);
  }

  #[test]
  fn from_str_rejects_wrong_prefix() {
    let acct = AccountId::generate();
    assert!(UserId::from_str(acct.as_str()).is_err());
  }

  #[test]
  fn serializes_as_bare_string() {
    let id = UserId::generate();
    let json = serde_json::to_string(&id).unwrap();
    assert_eq!(json, format!("\"{id}\""));
    let back: UserId = serde_json::from_str(&json).unwrap();
    assert_eq!(back, id);
  }

  #[test]
  fn ids_are_unique() {
    assert_ne!(UserId::generate(), UserId::generate());
  }
}
